import { readFile, mkdir, writeFile } from 'node:fs/promises';

const source = new URL('../zpr-dashboard/cmd/zpr-web-dashboard/static/app.css', import.meta.url);
const css = await readFile(source, 'utf8');
const palette = css.match(/^:root \{[\s\S]*?^\}/m)?.[0];
if (!palette) throw new Error('Shared palette block not found in app.css');
await mkdir(new URL('public/shared/', import.meta.url), { recursive: true });
await writeFile(new URL('public/shared/palette.css', import.meta.url),
  '/* Generated by sync-assets.mjs from the shared operator/Simulator palette. */\n' + palette + '\n');
